const ONES = ["sıfır", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz"];
const TENS = ["", "on", "yirmi", "otuz", "kırk", "elli", "altmış", "yetmiş", "seksen", "doksan"];
const SCALES = [
  [10n ** 18n, "kentilyon"],
  [10n ** 15n, "katrilyon"],
  [10n ** 12n, "trilyon"],
  [10n ** 9n, "milyar"],
  [10n ** 6n, "milyon"],
  [10n ** 3n, "bin"],
];
const MAX_NUMBER = 10n ** 21n - 1n;

export const VOWELS = new Set("aeıioöuüâîû");
const BACK_VOWELS = new Set("aıouâû");
const ROUNDED_VOWELS = new Set("oöuüû");
const VOICELESS = new Set("fstkçşhp");

// Loanword stems whose suffixes take front harmony despite a back last vowel.
const FRONT_EXCEPTIONS = new Set(["saat", "kontrol", "gol", "rol", "alkol", "petrol", "protokol", "hal", "kalp"]);

function belowThousand(n) {
  const words = [];
  const hundreds = Math.floor(n / 100);
  const rest = n % 100;
  if (hundreds) {
    if (hundreds > 1) words.push(ONES[hundreds]);
    words.push("yüz");
  }
  const tens = Math.floor(rest / 10);
  const ones = rest % 10;
  if (tens) words.push(TENS[tens]);
  if (ones) words.push(ONES[ones]);
  return words;
}

/** Cardinal reading of an integer. */
export function numberToWords(value) {
  let n = BigInt(value);
  if (n < 0n) return "eksi " + numberToWords(-n);
  if (n === 0n) return "sıfır";
  if (n > MAX_NUMBER) return digitsToWords(String(n));
  const words = [];
  for (const [scale, name] of SCALES) {
    const count = n / scale;
    n %= scale;
    if (count) {
      if (!(scale === 1000n && count === 1n)) words.push(...belowThousand(Number(count))); // "bin", never "bir bin"
      words.push(name);
    }
  }
  if (n) words.push(...belowThousand(Number(n)));
  return words.join(" ");
}

/** Read a digit string one digit at a time: "054" -> "sıfır beş dört". */
export function digitsToWords(digits) {
  return [...digits]
    .filter((d) => /\d/.test(d))
    .map((d) => ONES[Number(d)])
    .join(" ");
}

function lastVowel(word) {
  for (let i = word.length - 1; i >= 0; i--) if (VOWELS.has(word[i])) return word[i];
  return null;
}

/** [isBack, isRounded] for the stem's last vowel. */
function harmonyState(stem) {
  const words = stem.split(/\s+/).filter(Boolean);
  const lastWord = words.length ? words[words.length - 1] : stem;
  if (FRONT_EXCEPTIONS.has(lastWord) || lastWord.endsWith("saat")) {
    // also "kilovatsaat" (kWh)
    const v = lastVowel(lastWord) ?? "e";
    return [false, ROUNDED_VOWELS.has(v)];
  }
  const v = lastVowel(stem);
  if (v === null) return [false, false]; // e.g. bare consonant: default to front unrounded
  return [BACK_VOWELS.has(v), ROUNDED_VOWELS.has(v)];
}

const vowel4 = (back, rounded) => (back ? (rounded ? "u" : "ı") : rounded ? "ü" : "i");
const vowel2 = (back) => (back ? "a" : "e");

/**
 * Re-agree a suffix with the *spoken* stem. Writers harmonize suffixes with the reading they have in mind
 * ("5'te", "15.00'te"), but often get it wrong ("15.00'de", "SGK'ye"). Vowels and the d/t, c/ç alternations are
 * rebuilt from the stem; invariant morphemes (-ki after a locative, -yor, -ken) are kept as written.
 */
export function harmonizeSuffix(stem, suffix) {
  if (!suffix) return suffix;
  let s = suffix.toLowerCase();
  const stemL = stem.toLowerCase();
  const stemLast = stemL ? stemL[stemL.length - 1] : "";
  const stemEndsVowel = VOWELS.has(stemLast);

  // Buffer consonants: drop after consonant-final stems, add after vowel-final.
  if (!stemEndsVowel && s.length >= 2 && "ysnm".includes(s[0])) {
    if (s[0] === "y" && VOWELS.has(s[1])) s = s.slice(1); // "5'ye" -> "beşe", "5'yle" -> "beşle"
    else if (s[0] === "s" && "ıiuü".includes(s[1])) s = s.slice(1); // possessive: "5'si" -> "beşi" (not conditional -sA)
    else if (s[0] === "n" && "ıiuü".includes(s[1]) && s.slice(2, 3) === "n") s = s.slice(1); // genitive: "5'nin" -> "beşin"
    else if (("mn".includes(s[0]) && !VOWELS.has(s[1]) && s.slice(0, 2) !== "nc") || /^[mn][ıiuü]z/.test(s))
      // possessive -(I)m, -(I)mIz, -(I)nIz after "kuruş": "TL'mda", "TL'nız" -> "kuruşumda", "kuruşunuz"
      s = "ı" + s;
  } else if (!stemEndsVowel && (s === "m" || s === "n")) {
    s = "ı" + s; // possessive -m/-n: "25,50 TL'm" -> "... kuruşum"
  } else if (stemEndsVowel && VOWELS.has(s[0])) {
    // genitive -(n)In takes n ("6'ın" -> "altının"), everything else takes y
    if ("ıiuü".includes(s[0]) && s.slice(1, 2) === "n" && !VOWELS.has(s.slice(2, 3))) s = "n" + s;
    else s = "y" + s;
  }

  // -ki after a locative never harmonizes and sets the harmony of what follows:
  // "2023'teki", "1990'lardakiler", "2026'dakidir" (written -kı is re-spelled -ki)
  const fixedI = new Set ();
  for (let i = 2; i < s.length - 1; i++)
    if (s[i] === "k" && "ıi".includes(s[i + 1]) && "dt".includes(s[i - 2]) && "ae".includes(s[i - 1])) fixedI.add(i + 1);

  let [back, rounded] = harmonyState(stemL);
  let prev = stemLast;
  let out = "";
  for (let i = 0; i < s.length; i++) {
    let ch = s[i];
    if (fixedI.has(i)) {
      ch = "i";
      back = false;
      rounded = false;
    } else if ("aeâ".includes(ch)) {
      ch = vowel2(back);
      back = BACK_VOWELS.has(ch);
      rounded = false;
    } else if ("ıiuü".includes(ch)) {
      ch = vowel4(back, rounded);
      rounded = ROUNDED_VOWELS.has(ch);
    } else if ("oö".includes(ch)) {
      back = ch === "o";
      rounded = true;
    } else if ("dt".includes(ch) && i === 0) {
      ch = VOICELESS.has(prev) ? "t" : "d";
    } else if ("cç".includes(ch) && i === 0) {
      ch = VOICELESS.has(prev) ? "ç" : "c";
    }
    out += ch;
    prev = ch;
  }
  return out;
}

/**
 * Re-agree a separately written clitic (question mI and its inflections, dA) with the spoken stem. Only vowels
 * change: ("lira", "mi") -> "mı", ("altı", "de") -> "da", ("dokuz", "misiniz") -> "musunuz". Both lowercase.
 */
export function harmonizeClitic(stem, clitic) {
  let [back, rounded] = harmonyState(stem);
  let out = "";
  for (let ch of clitic) {
    if ("ae".includes(ch)) {
      ch = vowel2(back);
      back = BACK_VOWELS.has(ch);
      rounded = false;
    } else if ("ıiuü".includes(ch)) {
      ch = vowel4(back, rounded);
      rounded = ROUNDED_VOWELS.has(ch);
    }
    out += ch;
  }
  return out;
}

/** Attach a (re-harmonized) suffix to a spoken stem, handling dört -> dörd. */
export function attachSuffix(stem, suffix) {
  if (!suffix) return stem;
  const suf = harmonizeSuffix(stem, suffix);
  if (suf && VOWELS.has(suf[0]) && stem.endsWith("dört")) stem = stem.slice(0, -4) + "dörd";
  return stem + suf;
}

/** Ordinal reading: 1 -> birinci, 4 -> dördüncü, 20 -> yirminci. */
export function ordinalToWords(n) {
  let stem = numberToWords(n);
  const [back, rounded] = harmonyState(stem);
  const v = vowel4(back, rounded);
  const suf = VOWELS.has(stem[stem.length - 1]) ? "nc" + v : v + "nc" + v;
  if (VOWELS.has(suf[0]) && stem.endsWith("dört")) stem = stem.slice(0, -4) + "dörd";
  return stem + suf;
}

/** Read the part after the decimal comma: "5" -> beş, "05" -> sıfır beş, "25" -> yirmi beş. */
export function readDecimalFraction(digits) {
  if (!digits) return "";
  if (digits.length > 3) return digitsToWords(digits);
  return readDigitGroup(digits);
}

/** Read a digit group keeping leading zeros: "05" -> "sıfır beş", "693" -> "altı yüz doksan üç". */
export function readDigitGroup(group) {
  const rest = group.replace(/^0+/, "");
  const parts = Array(group.length - rest.length).fill("sıfır");
  if (rest) parts.push(numberToWords(BigInt(rest)));
  return parts.join(" ");
}

const GROUP_PATTERNS = {
  5: [3, 2],
  6: [3, 3],
  7: [3, 2, 2],
  8: [3, 3, 2],
  9: [3, 3, 3],
  10: [3, 3, 2, 2],
  11: [3, 3, 3, 2],
};

/** Read an identifier-like digit string in speakable groups (3-3-2-2 style). */
export function readLongDigits(digits) {
  const n = digits.length;
  if (n <= 4) return readDigitGroup(digits);
  let sizes = GROUP_PATTERNS[n];
  if (!sizes) {
    sizes = Array(Math.floor(n / 3)).fill(3);
    if (n % 3 === 1) {
      sizes[sizes.length - 1] = 2;
      sizes.push(2);
    } else if (n % 3 === 2) sizes.push(2);
  }
  const groups = [];
  let i = 0;
  for (const size of sizes) {
    groups.push(digits.slice(i, i + size));
    i += size;
  }
  return groups.map(readDigitGroup).join(", ");
}
